 dict(head="أَسْتَعِدُّ جَيِّدًا لِرِحْلَتي",sana="أُحَضِّرُ الْمُعَدّاتِ الْمُناسِبَةَ قَبْلَ أَيِّ رِحْلَةٍ جَديدَةٍ.",fact="واقي الرُّكْبَةِ وَالْخوذَةُ ضَرورِيّانِ لِلسَّلامَةِ عِنْدَ التَّزَلُّجِ.",dilemma="أَريدُ أَنْ أَتَزَلَّجَ لِأَوَّلِ مَرَّةٍ وَأَخافُ قَليلًا… ماذا أَفْعَلُ؟",model="أَسْتَعينُ بِمُرْشِدٍ، وَأَبْدَأُ بِخُطُواتٍ بَسيطَةٍ حَتّى أَكْتَسِبَ الثِّقَةَ."),
 [["أَيْنَ سَتَقْضي الْأُسْرَةُ عُطْلَتَها؟",["جِبالُ سُويسْرا الثَّلْجِيَّةُ","شَواطِئُ الْبَحْرِ","الصَّحْراءُ"]],["لِماذا هِيَ عُطْلَةُ أَحْلامٍ لِلطِّفْلِ؟",["سَيَرى الثَّلْجَ لِأَوَّلِ مَرَّةٍ","لِأَنَّها رَخيصَةٌ","لِأَنَّها قَريبَةٌ"]],["ماذا تُحَضِّرُ الْأُمُّ؟",["قائِمَةَ الْمُعَدّاتِ","الطَّعامَ فَقَطْ","الْمَلابِسَ الصَّيْفِيَّةَ"]],["ماذا يَفْعَلُ الْمُرْشِدونَ؟",["يُساعِدونَ في اخْتِيارِ الْأَنْشِطَةِ","يَطْبُخونَ الطَّعامَ","يَقودونَ السَّيّارَةَ"]],["«واقي الرُّكْبَةِ» يُسْتَخْدَمُ لِـ:",["حِمايَةِ الرُّكْبَةِ","حِمايَةِ الرَّأْسِ","حِمايَةِ الْيَدَيْنِ"]],["«مُتَحَمِّسٌ» تَعْني:",["excited","sad","afraid"]]],
